import math
    import random
    import time

    LANGUAGE_WRAPPER = 'In a combinatorial game, a single positive integer n with 1 ≤ n ≤ {upper_bound} is written on a blackboard. Two players alternate moves; on a move, a player selects any current integer k > {threshold} and replaces it by either {branch_a} or {branch_b} non-negative integers whose pairwise differences are at most 1 and whose sum equals k. Integers ≤ {threshold} cannot be split further. The game ends when no valid move exists; the last player to move wins. Assuming optimal play, determine how many values of n in [1, {upper_bound}] make the first player win.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Generate a non-trivial impartial splitting game instance
# Constraints: upper_bound moderately large; threshold small; branches distinct with mixed parity
def compute_count(upper_bound, threshold, branches):
    # Sprague-Grundy DP for single-heap values up to upper_bound
    G = [0] * (upper_bound + 1)
    # Base: k <= threshold => G[k] = 0
    for k in range(threshold + 1, upper_bound + 1):
        opts = []
        for s in branches:
            q, r = divmod(k, s)
            xor_val = 0
            if r % 2 == 1:
                xor_val ^= G[q + 1]
            if (s - r) % 2 == 1:
                xor_val ^= G[q]
            opts.append(xor_val)
        # mex of options
        seen = set(opts)
        g = 0
        while g in seen:
            g += 1
        G[k] = g
    return sum(1 for n in range(1, upper_bound + 1) if G[n] != 0)
# Try a few times to ensure interesting instance
for _ in range(40):
    upper_bound = rng.randint(12000, 45000)
    threshold = rng.randint(1, min(6, max(1, upper_bound // 12)))
    # Choose branches with mixed parity and small-ish sizes to keep DP fast
    odd_choices = [3, 5, 7, 9]
    even_choices = [4, 6, 8]
    branch_a = rng.choice(odd_choices)
    branch_b = rng.choice(even_choices)
    # Occasionally swap parity roles
    if rng.random() < 0.4:
        branch_a, branch_b = branch_b, branch_a
    # Ensure distinct
    if branch_a == branch_b:
        continue
    # Compute count to check non-triviality
    count = compute_count(upper_bound, threshold, [branch_a, branch_b])
    frac = count / float(upper_bound)
    # Keep instances that are neither too easy nor too skewed
    if 0.35 <= frac <= 0.65:
        return {
            'upper_bound': upper_bound,
            'threshold': threshold,
            'branch_a': branch_a,
            'branch_b': branch_b
        }
# Fallback: deterministic safe parameters
upper_bound = 20000
threshold = 2
branch_a = 5
branch_b = 4
return {
    'upper_bound': upper_bound,
    'threshold': threshold,
    'branch_a': branch_a,
    'branch_b': branch_b
}

    def verifier(assign):
# Verify parameters and compute the exact count of winning n using Sprague-Grundy theory.
# Returns (True, answer) if valid; otherwise (False, None).
# Validate presence and types
required = ['upper_bound', 'threshold', 'branch_a', 'branch_b']
for key in required:
    if key not in assign:
        # Missing slot
        return (False, None)
ub = assign['upper_bound']
th = assign['threshold']
a = assign['branch_a']
b = assign['branch_b']
# Type checks
if not all(isinstance(x, int) for x in [ub, th, a, b]):
    # All parameters must be integers
    return (False, None)
# Domain checks
if ub < 1000 or ub > 100000:
    # Upper bound must be reasonably large for difficulty
    return (False, None)
if th < 1 or th >= ub:
    # Threshold must be at least 1 and less than upper_bound
    return (False, None)
if a < 3 or b < 3 or a > 30 or b > 30:
    # Branch sizes must be in a sane range
    return (False, None)
if a == b:
    # Branch sizes must be distinct
    return (False, None)
# Encourage mixed parity to avoid trivial degeneracies
if (a % 2) == (b % 2):
    return (False, None)
# Compute Grundy numbers G[k] for k up to ub
branches = [a, b]
G = [0] * (ub + 1)
# Base cases: k <= th => G[k] = 0
for k in range(th + 1, ub + 1):
    opts = []
    for s in branches:
        q, r = divmod(k, s)
        xor_val = 0
        # XOR contributions depend only on parity of counts
        if r % 2 == 1:
            xor_val ^= G[q + 1]
        if (s - r) % 2 == 1:
            xor_val ^= G[q]
        opts.append(xor_val)
    # mex of available options' nim-sums
    seen = set(opts)
    g = 0
    while g in seen:
        g += 1
    G[k] = g
answer = sum(1 for n in range(1, ub + 1) if G[n] != 0)
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

